#include <stdio.h>

void rotate_left(int a[], int n, int k) {
    int rotated[100];
    for (int i = 0; i < n; i++) {
        rotated[i] = a[(i + k) % n];
    }
    for (int i = 0; i < n; i++) {
        a[i] = rotated[i];
    }
}

int main() {
    int a[] = {1, 2, 3, 4, 5, 6};
    rotate_left(a, 6, 2);
    for (int i = 0; i < 6; i++) printf("%d ", a[i]);
    printf("\n");
    return 0;
}
